import {ActionMenu, ActionList, IconButton, Label, Spinner} from '@primer/react'
import {
  KebabHorizontalIcon,
  PencilIcon,
  GitBranchIcon,
  StopIcon,
  BookmarkIcon,
  TrashIcon,
  AlertIcon,
  CheckIcon,
} from '@primer/octicons-react'
import type {Codespace} from './codespaces-types'
import {getEditorIcon, getExportLabel} from './codespace-action-menu-helpers'
import {useCodespaceActionMenuState} from './use-codespace-action-menu-state'

interface CodespaceActionMenuProps {
  codespace: Codespace
  showActions: boolean
  onDeleteClick: (codespace: Codespace) => void
  onChangeMachineType: (codespace: Codespace) => void
  onRenameClick: (codespace: Codespace) => void
  onExportClick: (codespace: Codespace) => void
  onActionComplete?: () => void
}

export function CodespaceActionMenu({
  codespace,
  showActions,
  onDeleteClick,
  onChangeMachineType,
  onRenameClick,
  onExportClick,
  onActionComplete,
}: CodespaceActionMenuProps) {
  const {isStopping, autoDeleteEnabled, handleStop, handleAutoDeleteToggle, sendAnalyticsEvent} =
    useCodespaceActionMenuState(codespace, onActionComplete)
  if (!showActions) return null

  const exportDisabled = codespace.isFailed || codespace.isBlocking
  const canOpenInEditors = !codespace.linkDisabled && !codespace.startDisabled

  return (
    <ActionMenu>
      <ActionMenu.Anchor>
        <IconButton
          icon={KebabHorizontalIcon}
          aria-label={`More actions for ${codespace.displayName}`}
          variant="invisible"
          size="small"
        />
      </ActionMenu.Anchor>
      <ActionMenu.Overlay align="end">
        <ActionList>
          <ActionList.Item onSelect={() => onRenameClick(codespace)}>
            <ActionList.LeadingVisual>
              <PencilIcon />
            </ActionList.LeadingVisual>
            Rename
          </ActionList.Item>
          {exportDisabled ? (
            <ActionList.Item disabled>
              <ActionList.LeadingVisual>
                {codespace.isBlocking ? <Spinner size="small" /> : <GitBranchIcon />}
              </ActionList.LeadingVisual>
              {getExportLabel(codespace)}
              {codespace.isBlocking && codespace.blockingOperationText && (
                <ActionList.Description>{codespace.blockingOperationText}</ActionList.Description>
              )}
            </ActionList.Item>
          ) : (
            <ActionList.Item onSelect={() => onExportClick(codespace)}>
              <ActionList.LeadingVisual>
                <GitBranchIcon />
              </ActionList.LeadingVisual>
              {getExportLabel(codespace)}
            </ActionList.Item>
          )}
          {codespace.allowChangeMachineType && (
            <ActionList.Item
              disabled={codespace.isFailed || codespace.isBlocking}
              onSelect={() => onChangeMachineType(codespace)}
            >
              <ActionList.LeadingVisual>
                {codespace.isBlocking ? <Spinner size="small" /> : <PencilIcon />}
              </ActionList.LeadingVisual>
              Change machine type
              {codespace.isBlocking && codespace.blockingOperationText && (
                <ActionList.Description>{codespace.blockingOperationText}</ActionList.Description>
              )}
            </ActionList.Item>
          )}
          {codespace.suspendable &&
            (codespace.isBlocking || isStopping ? (
              <ActionList.Item disabled>
                <ActionList.LeadingVisual>
                  <Spinner size="small" />
                </ActionList.LeadingVisual>
                <span>{isStopping ? 'Stopping...' : 'Stop codespace'}</span>
                {codespace.blockingOperationText && (
                  <ActionList.Description>{codespace.blockingOperationText}</ActionList.Description>
                )}
              </ActionList.Item>
            ) : (
              <ActionList.Item onSelect={handleStop}>
                <ActionList.LeadingVisual>
                  <StopIcon />
                </ActionList.LeadingVisual>
                Stop codespace
              </ActionList.Item>
            ))}
          {codespace.retentionPeriodDays != null && (
            <>
              <ActionList.Divider />
              {codespace.keepDisabled ? (
                <ActionList.Item disabled>
                  <ActionList.LeadingVisual>
                    <BookmarkIcon />
                  </ActionList.LeadingVisual>
                  Auto-delete codespace
                  <ActionList.Description>Action disabled by your organization</ActionList.Description>
                  <ActionList.TrailingVisual>
                    <CheckIcon />
                  </ActionList.TrailingVisual>
                </ActionList.Item>
              ) : (
                <ActionList.Item onSelect={handleAutoDeleteToggle}>
                  <ActionList.LeadingVisual>
                    <BookmarkIcon />
                  </ActionList.LeadingVisual>
                  Auto-delete codespace
                  {autoDeleteEnabled && (
                    <ActionList.TrailingVisual>
                      <CheckIcon />
                    </ActionList.TrailingVisual>
                  )}
                </ActionList.Item>
              )}
            </>
          )}

          <ActionList.Divider />
          {codespace.editors.map(editor => {
            const EditorIcon = getEditorIcon(editor.icon)
            if (canOpenInEditors) {
              return (
                <ActionList.LinkItem key={editor.id} href={editor.url} target="_blank" rel="noopener noreferrer">
                  <ActionList.LeadingVisual>
                    <EditorIcon />
                  </ActionList.LeadingVisual>
                  {editor.label}
                  {editor.beta && (
                    <ActionList.TrailingVisual>
                      <Label variant="success">Preview</Label>
                    </ActionList.TrailingVisual>
                  )}
                </ActionList.LinkItem>
              )
            }
            return (
              <ActionList.Item key={editor.id} disabled>
                <ActionList.LeadingVisual>
                  {codespace.isBlocking ? <Spinner size="small" /> : <AlertIcon />}
                </ActionList.LeadingVisual>
                {editor.label}
                <ActionList.Description>
                  {codespace.isBlocking ? codespace.blockingOperationText : 'Start is temporarily disabled'}
                </ActionList.Description>
                {editor.beta && (
                  <ActionList.TrailingVisual>
                    <Label variant="success">Preview</Label>
                  </ActionList.TrailingVisual>
                )}
              </ActionList.Item>
            )
          })}
          {codespace.deletable && (
            <>
              <ActionList.Divider />
              <ActionList.Item
                variant="danger"
                onSelect={() => {
                  sendAnalyticsEvent('codespace_destroy.click', 'CODESPACES_PAGE')
                  onDeleteClick(codespace)
                }}
              >
                <ActionList.LeadingVisual>
                  <TrashIcon />
                </ActionList.LeadingVisual>
                Delete
              </ActionList.Item>
            </>
          )}
        </ActionList>
      </ActionMenu.Overlay>
    </ActionMenu>
  )
}
