import {verifiedFetch, verifiedFetchJSON} from '@github-ui/verified-fetch'
import {useAnalytics} from '@github-ui/use-analytics'
import type React from 'react'
import {useCallback, useEffect, useState} from 'react'
import type {Codespace} from './codespaces-types'

export function useCodespaceActionMenuState(codespace: Codespace, onActionComplete?: () => void) {
  const [isStopping, setIsStopping] = useState(false)
  const [autoDeleteEnabled, setAutoDeleteEnabled] = useState(codespace.keepEnabled)
  const {sendAnalyticsEvent} = useAnalytics()

  useEffect(() => {
    setAutoDeleteEnabled(codespace.keepEnabled)
  }, [codespace.id, codespace.keepEnabled])

  const handleStop = useCallback(async () => {
    setIsStopping(true)
    sendAnalyticsEvent('codespace_suspend.click', 'CODESPACES_PAGE')
    try {
      const response = await verifiedFetchJSON(codespace.paths.suspend, {
        method: 'POST',
      })

      if (response.ok) {
        onActionComplete?.()
      }
    } finally {
      setIsStopping(false)
    }
  }, [codespace.paths.suspend, onActionComplete, sendAnalyticsEvent])

  const handleAutoDeleteToggle = useCallback(
    async (event: React.MouseEvent<HTMLElement> | React.KeyboardEvent<HTMLElement>) => {
      event.preventDefault()
      const newValue = !autoDeleteEnabled
      setAutoDeleteEnabled(newValue)
      try {
        const response = await verifiedFetch(codespace.paths.codespace, {
          method: 'PATCH',
          headers: {
            Accept: 'application/json',
            'Content-Type': 'application/x-www-form-urlencoded',
          },
          body: new URLSearchParams({'codespace[keep]': newValue ? 'false' : 'true'}),
        })

        if (!response.ok) {
          throw new Error(`HTTP ${response.status}`)
        }
      } catch {
        setAutoDeleteEnabled(!newValue)
      }
    },
    [codespace.paths.codespace, autoDeleteEnabled],
  )

  return {
    isStopping,
    autoDeleteEnabled,
    handleStop,
    handleAutoDeleteToggle,
    sendAnalyticsEvent,
  }
}
