import {useState, useCallback, useEffect, useRef} from 'react'
import {Spinner, Banner, FormControl, TextInput, RadioGroup, Radio, BranchName} from '@primer/react'
import {Dialog} from '@primer/react/experimental'
import {GitBranchIcon} from '@primer/octicons-react'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {useCurrentRepository} from '@github-ui/current-repository'
import type {Codespace} from './codespaces-types'

type ExportDialogState = 'checking' | 'ready' | 'exporting' | 'done'
type ExportTarget = 'branch' | 'fork' | 'repository'
type ExportControlStatus = 'exportable' | 'exporting' | 'exported'

interface ExportControlResponse {
  exportTarget: ExportTarget
  exportTargetUrl: string
  exportStatus: ExportControlStatus
  existingForkNwo: string | null
}

const POLL_INITIAL_MS = 1000
const POLL_BACKOFF = 1.5
const POLL_MAX_MS = 5000

function getDialogTitle(codespace: Codespace) {
  if (codespace.isUnpublished) return 'Publish to a new repository'
  if (codespace.needsForkToPush) return 'Export changes to a fork'
  return 'Export changes to a branch'
}

function getCheckingMessage(codespace: Codespace) {
  if (codespace.isUnpublished) return 'Checking repository status'
  if (codespace.needsForkToPush) return 'Checking fork status'
  return 'Checking branch status'
}

function getSuccessMessage(target: ExportTarget) {
  if (target === 'repository') return 'Your changes have been published to a new repository.'
  if (target === 'fork') return 'Your changes have been exported to a new fork.'
  return 'Your changes have been exported to a new branch.'
}

function getCreateLabel(target: ExportTarget) {
  return `Create ${target}`
}

function getViewLabel(target: ExportTarget) {
  return `See ${target}`
}

function slugifyDisplayName(displayName: string) {
  return displayName.trim().replace(/\s+/g, '-').slice(0, 100)
}

interface ExportCodespaceDialogProps {
  codespace: Codespace | null
  onClose: () => void
  onExported: () => void
}

export function ExportCodespaceDialog({codespace, onClose, onExported}: ExportCodespaceDialogProps) {
  if (!codespace) return null
  return <ExportCodespaceDialogInner codespace={codespace} onClose={onClose} onExported={onExported} />
}

function ExportCodespaceDialogInner({
  codespace,
  onClose,
  onExported,
}: {
  codespace: Codespace
  onClose: () => void
  onExported: () => void
}) {
  const repository = useCurrentRepository()
  const [state, setState] = useState<ExportDialogState>('checking')
  const [error, setError] = useState<string | null>(null)
  const [exportControl, setExportControl] = useState<ExportControlResponse | null>(null)
  const [publishName, setPublishName] = useState('')
  const [visibility, setVisibility] = useState<'public' | 'private'>('private')
  const pollRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const codespaceRef = useRef(codespace)
  const onExportedRef = useRef(onExported)
  const exportControlRef = useRef<ExportControlResponse | null>(null)

  useEffect(() => {
    codespaceRef.current = codespace
    onExportedRef.current = onExported
  }, [codespace, onExported])

  useEffect(() => {
    exportControlRef.current = exportControl
  }, [exportControl])

  useEffect(() => {
    return () => {
      if (pollRef.current) clearTimeout(pollRef.current)
    }
  }, [])

  const fallbackControl = useCallback((): ExportControlResponse => {
    const exportTarget: ExportTarget = codespace.isUnpublished
      ? 'repository'
      : codespace.needsForkToPush
        ? 'fork'
        : 'branch'

    return {
      exportTarget,
      exportTargetUrl:
        exportTarget === 'branch'
          ? (codespace.exportBranchUrl ?? codespace.paths.codespace)
          : codespace.paths.codespace,
      exportStatus: 'exportable',
      existingForkNwo: null,
    }
  }, [codespace])

  const startPolling = useCallback((control: ExportControlResponse) => {
    function poll(delayMs: number) {
      pollRef.current = setTimeout(async () => {
        const cs = codespaceRef.current
        if (!cs) return

        try {
          const response = await verifiedFetchJSON(cs.paths.exported)

          if (response.status === 200) {
            setExportControl(control)
            setState('done')
            onExportedRef.current()
            return
          }

          if (response.status === 202 || response.status === 404) {
            poll(Math.min(delayMs * POLL_BACKOFF, POLL_MAX_MS))
            return
          }

          setState('ready')
          setError(
            response.status === 408
              ? 'Your codespace export did not complete. Please try again.'
              : 'Your codespace does not appear to be exporting. Please try again.',
          )
        } catch {
          setState('ready')
          setError('Failed to check export status.')
        }
      }, delayMs)
    }

    poll(POLL_INITIAL_MS)
  }, [])

  useEffect(() => {
    setState('checking')
    setError(null)
    setExportControl(null)
    setPublishName(slugifyDisplayName(codespace.displayName || codespace.name))
    setVisibility('private')

    let cancelled = false

    void (async () => {
      try {
        const url = new URL(codespace.paths.exportControl, window.location.origin)
        if (codespace.needsForkToPush) url.searchParams.set('needs_fork', 'true')

        const response = await verifiedFetchJSON(url.toString())

        if (!response.ok) throw new Error('Failed to load export control')

        const control = (await response.json()) as ExportControlResponse
        if (cancelled) return

        setExportControl(control)

        if (control.exportStatus === 'exporting') {
          setState('exporting')
          startPolling(control)
        } else if (control.exportStatus === 'exported') {
          setState('done')
        } else {
          setState('ready')
        }
      } catch {
        if (cancelled) return
        const control = fallbackControl()
        setExportControl(control)
        setState(control.exportStatus === 'exported' ? 'done' : 'ready')
      }
    })()

    return () => {
      cancelled = true
    }
  }, [codespace, fallbackControl, startPolling])

  const handleExport = useCallback(async () => {
    const control = exportControlRef.current ?? fallbackControl()
    setState('exporting')
    setError(null)

    try {
      const url = new URL(codespace.paths.export, window.location.origin)
      if (codespace.needsForkToPush) url.searchParams.set('fork', 'true')
      if (codespace.isUnpublished) {
        url.searchParams.set('name', publishName.trim())
        url.searchParams.set('visibility', visibility)
      }

      const response = await verifiedFetchJSON(url.toString(), {method: 'POST'})

      if (response.status === 202) {
        startPolling(control)
      } else {
        setState('ready')
        setError('Failed to start export. Please try again.')
      }
    } catch {
      setState('ready')
      setError('Failed to start export.')
    }
  }, [codespace, publishName, visibility, startPolling, fallbackControl])

  const target = exportControl?.exportTarget ?? fallbackControl().exportTarget
  const targetUrl = exportControl?.exportTargetUrl ?? fallbackControl().exportTargetUrl
  const existingForkNwo = exportControl?.existingForkNwo ?? null
  const currentRepoNwo =
    repository?.ownerLogin && repository?.name ? `${repository.ownerLogin}/${repository.name}` : 'this repository'

  const canSubmitPublish = publishName.trim().length > 0

  const closeButton = {content: state === 'done' ? 'Close' : 'Cancel', onClick: onClose}

  const primaryButton =
    state === 'checking'
      ? {
          content: (
            <span className="d-flex flex-items-center" style={{gap: 'var(--base-size-8)'}}>
              <Spinner size="small" />
              <span>{getCheckingMessage(codespace)}</span>
            </span>
          ),
          buttonType: 'primary' as const,
          disabled: true,
          onClick: () => {},
        }
      : state === 'done'
        ? {
            content: getViewLabel(target),
            buttonType: 'primary' as const,
            onClick: () => {
              window.open(targetUrl, '_blank')
              onClose()
            },
          }
        : state === 'exporting'
          ? {
              content: (
                <span className="d-flex flex-items-center" style={{gap: 'var(--base-size-8)'}}>
                  <Spinner size="small" />
                  <span>{`Creating ${target}...`}</span>
                </span>
              ),
              buttonType: 'primary' as const,
              disabled: true,
              onClick: () => {},
            }
          : {
              content: getCreateLabel(target),
              buttonType: 'primary' as const,
              onClick: handleExport,
              disabled: codespace.isUnpublished ? !canSubmitPublish : false,
            }

  const renderReadyBody = () => {
    if (codespace.isUnpublished) {
      return (
        <>
          <p className="tmp-mb-3">This will create a new repository and push up your work.</p>
          <FormControl>
            <FormControl.Label>Name</FormControl.Label>
            <TextInput
              value={publishName}
              onChange={e => setPublishName(e.target.value)}
              autoFocus
              block
              maxLength={100}
            />
          </FormControl>
          <div className="border-top color-border-muted tmp-mt-3 tmp-pt-3">
            <RadioGroup
              name="visibility"
              onChange={(value: string | null) => {
                if (value === 'public' || value === 'private') setVisibility(value)
              }}
            >
              <RadioGroup.Label>Visibility</RadioGroup.Label>
              <FormControl>
                <Radio value="public" checked={visibility === 'public'} />
                <FormControl.Label>Public</FormControl.Label>
                <FormControl.Caption>
                  Anyone on the internet can see this repository. You choose who can commit.
                </FormControl.Caption>
              </FormControl>
              <FormControl>
                <Radio value="private" checked={visibility === 'private'} />
                <FormControl.Label>Private</FormControl.Label>
                <FormControl.Caption>You choose who can see and commit to this repository.</FormControl.Caption>
              </FormControl>
            </RadioGroup>
          </div>
        </>
      )
    }

    if (codespace.needsForkToPush) {
      return existingForkNwo ? (
        <p>
          You do not have write access to this codespace&apos;s repository. This will reassign your codespace to your
          existing fork of this repository, <strong>{existingForkNwo}</strong>, and export your changes to a new branch.
        </p>
      ) : (
        <p>
          You do not have write access to this codespace&apos;s repository. This will create a new fork of{' '}
          <strong>{currentRepoNwo}</strong>, reassign your codespace to that fork, and export your changes to a new
          branch.
        </p>
      )
    }

    return (
      <>
        <p className="tmp-mb-3">This will create a new branch with any unpushed changes</p>
        <BranchName>
          <GitBranchIcon size={12} className="v-align-middle" />
          <span>{codespace.exportBranchName}</span>
        </BranchName>
      </>
    )
  }

  return (
    <Dialog title={getDialogTitle(codespace)} onClose={onClose} footerButtons={[closeButton, primaryButton]}>
      <Dialog.Body>
        {error && <Banner hideTitle title="Error" variant="critical" description={error} className="tmp-mb-3" />}
        {state === 'checking' ? (
          <div className="d-flex flex-items-center" style={{gap: 'var(--base-size-8)'}}>
            <Spinner size="small" />
            <span>{getCheckingMessage(codespace)}</span>
          </div>
        ) : state === 'done' ? (
          <p>{getSuccessMessage(target)}</p>
        ) : (
          renderReadyBody()
        )}
      </Dialog.Body>
    </Dialog>
  )
}
