import {Banner, Link} from '@primer/react'
import {useState} from 'react'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import type {Codespace, CodespacesData} from './codespaces-types'
import {CodespacesHeaderComponent} from './CodespacesHeader'
import {CodespacesList} from './CodespacesList'
import {DeleteCodespaceDialog} from './DeleteCodespaceDialog'
import {ChangeMachineTypeDialog} from './ChangeMachineTypeDialog'
import {RenameCodespaceDialog} from './RenameCodespaceDialog'
import {ExportCodespaceDialog} from './ExportCodespaceDialog'
import {useCodespacesData, useInvalidateCodespacesData, useCodespacesAlive} from './use-codespaces-data'
import {useCodespacesCreateAction} from './use-codespaces-create-action'

interface CodespacesTabReactProps {
  codespacesPath?: string
  currentBranchName?: string
  createRef?: string
}

export function CodespacesTabReact({codespacesPath, currentBranchName, createRef}: CodespacesTabReactProps) {
  const {data} = useCodespacesData(codespacesPath)
  const invalidate = useInvalidateCodespacesData(codespacesPath)
  const createAction = useCodespacesCreateAction(data?.header, createRef, invalidate)
  const [deletingCodespace, setDeletingCodespace] = useState<Codespace | null>(null)
  const [changingMachineType, setChangingMachineType] = useState<Codespace | null>(null)
  const [renamingCodespace, setRenamingCodespace] = useState<Codespace | null>(null)
  const [exportingCodespace, setExportingCodespace] = useState<Codespace | null>(null)
  const [optimisticallyRemoved, setOptimisticallyRemoved] = useState<Set<number>>(() => new Set())

  useCodespacesAlive(data?.aliveChannel, codespacesPath)

  const handleDeleteSettled = async (codespace: Codespace) => {
    await invalidate()
    setOptimisticallyRemoved(prev => {
      const next = new Set(prev)
      next.delete(codespace.id)
      return next
    })
  }

  const maintenanceNotice = data?.header.maintenanceNotice ?? null
  const [dismissedMaintenancePath, setDismissedMaintenancePath] = useState<string | null>(null)
  const maintenanceDismissed = maintenanceNotice !== null && dismissedMaintenancePath === maintenanceNotice.dismissPath

  const dismissMaintenanceNotice = async () => {
    if (!maintenanceNotice) return
    setDismissedMaintenancePath(maintenanceNotice.dismissPath)

    try {
      await verifiedFetchJSON(maintenanceNotice.dismissPath, {method: 'POST'})
    } catch {
      // Dismissal is best-effort; the banner stays hidden for this session
    }
  }

  if (!data) return null

  const filteredCodespaces = data.codespaces.filter(cs => !optimisticallyRemoved.has(cs.id))
  const filteredData: CodespacesData = {
    ...data,
    codespaces: filteredCodespaces,
  }

  const {header} = filteredData
  const {createNotice} = header

  return (
    <div className="width-full">
      <CodespacesHeaderComponent header={header} createRef={createRef} createAction={createAction} />

      {header.maintenanceNotice && !maintenanceDismissed && (
        <Banner
          hideTitle
          title="Codespaces maintenance notice"
          variant="warning"
          description={
            <span>
              {header.maintenanceNotice.message}{' '}
              <Link inline href={header.maintenanceNotice.linkUrl}>
                {header.maintenanceNotice.linkText}
              </Link>
              .
            </span>
          }
          onDismiss={dismissMaintenanceNotice}
          className="mx-2 mt-2"
        />
      )}

      {filteredData.ssoWarning && (
        <Banner
          hideTitle
          title="SSO warning"
          variant="warning"
          description={filteredData.ssoWarning.message}
          className="mx-2 mt-2"
        />
      )}

      {filteredData.pullRequestWarning && (
        <Banner
          hideTitle
          title="Pull request warning"
          variant="critical"
          description={
            <span>
              {filteredData.pullRequestWarning.message}
              {filteredData.pullRequestWarning.linkUrl && filteredData.pullRequestWarning.linkText && (
                <>
                  {' You may be able to '}
                  <Link inline href={filteredData.pullRequestWarning.linkUrl}>
                    {filteredData.pullRequestWarning.linkText}
                  </Link>
                  .
                </>
              )}
            </span>
          }
          className="mx-2 mt-2"
        />
      )}

      {createNotice && (
        <Banner
          hideTitle
          title="Create notice"
          variant="critical"
          description={
            <span>
              {createNotice.message}
              {createNotice.linkUrl && createNotice.linkText && (
                <>
                  {' '}
                  <Link inline href={createNotice.linkUrl}>
                    {createNotice.linkText}
                  </Link>
                </>
              )}
            </span>
          }
          className="mx-2 mt-2"
        />
      )}

      <CodespacesList
        data={filteredData}
        currentBranchName={currentBranchName}
        createAction={createAction}
        onDeleteClick={setDeletingCodespace}
        onChangeMachineType={setChangingMachineType}
        onRenameClick={setRenamingCodespace}
        onExportClick={setExportingCodespace}
        onActionComplete={invalidate}
      />

      {!createNotice && header.billableOwnerName && (
        <div className="tmp-p-3 mb-0 text-small color-fg-subtle border-top color-border-muted">
          Codespace usage for this repository is paid for by{' '}
          <span className="text-bold">{header.billableOwnerName}</span>.
        </div>
      )}

      <DeleteCodespaceDialog
        codespace={deletingCodespace}
        onClose={() => setDeletingCodespace(null)}
        onDeleted={codespace => setOptimisticallyRemoved(prev => new Set(prev).add(codespace.id))}
        onDeleteConfirmed={handleDeleteSettled}
        onError={handleDeleteSettled}
      />
      <ChangeMachineTypeDialog
        codespace={changingMachineType}
        onClose={() => setChangingMachineType(null)}
        onUpdated={invalidate}
      />
      <RenameCodespaceDialog
        codespace={renamingCodespace}
        onClose={() => setRenamingCodespace(null)}
        onRenamed={invalidate}
      />
      <ExportCodespaceDialog
        codespace={exportingCodespace}
        onClose={() => setExportingCodespace(null)}
        onExported={invalidate}
      />
    </div>
  )
}
