import type {CreateFormFields} from './codespaces-types'

export interface CreateResponse {
  codespace_url?: string
  loading_url?: string
  error?: string
  error_type?: string
}

export const GENERIC_CREATE_ERROR = 'Could not create a codespace. Try again.'

export function resolveCreateRef(fields: CreateFormFields, createRef?: string): string | undefined {
  if (fields.pullRequestId != null) return undefined
  return createRef
}

export function withRefQueryParam(urlString: string, createRef?: string): string {
  if (!createRef) return urlString

  const url = new URL(urlString, 'https://github.local')
  url.searchParams.set('ref', createRef)
  return `${url.pathname}${url.search}${url.hash}`
}

export function buildCreateFormData(fields: CreateFormFields, resolvedCreateRef?: string) {
  const formData = new FormData()

  if (fields.repositoryId != null) formData.set('codespace[repository_id]', String(fields.repositoryId))
  if (resolvedCreateRef != null) formData.set('codespace[ref]', resolvedCreateRef)
  if (fields.pullRequestId != null) formData.set('codespace[pull_request_id]', String(fields.pullRequestId))
  if (fields.expectedBillableOwnerId != null) {
    formData.set('expected_billable_owner_id', String(fields.expectedBillableOwnerId))
  }
  if (fields.openInDeeplink) formData.set('open_in_deeplink', 'true')
  if (fields.devcontainerPath != null) formData.set('codespace[devcontainer_path]', fields.devcontainerPath)

  return formData
}

export async function readCreateResponse(response: Response): Promise<CreateResponse | null> {
  try {
    return (await response.json()) as CreateResponse
  } catch {
    return null
  }
}

export async function readCreateDestination(response: Response): Promise<string | null> {
  const json = await readCreateResponse(response)
  return json?.codespace_url ?? json?.loading_url ?? null
}
