import {Banner, RadioGroup, Radio, FormControl, Spinner} from '@primer/react'
import {Dialog} from '@primer/react/experimental'
import {useState, useEffect, useCallback} from 'react'
import {verifiedFetch} from '@github-ui/verified-fetch'
import type {Codespace} from './codespaces-types'

interface SkuOption {
  name: string
  displayName: string
  cpus: number
  memoryGb: number
  storageGb: number
  enabled: boolean
  note: string | null
}

interface SkuData {
  skus: SkuOption[]
  currentSku: string | null
  currentSkuDisallowed: boolean
  codespaceName: string
}

interface ChangeMachineTypeDialogProps {
  codespace: Codespace | null
  onClose: () => void
  onUpdated: () => void
}

export function ChangeMachineTypeDialog({codespace, onClose, onUpdated}: ChangeMachineTypeDialogProps) {
  const [skuData, setSkuData] = useState<SkuData | null>(null)
  const [loading, setLoading] = useState(true)
  const [selectedSku, setSelectedSku] = useState<string | null>(null)
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    if (!codespace) return

    let cancelled = false
    setLoading(true)
    setError(null)
    setSkuData(null)
    setSelectedSku(null)
    setSaving(false)

    const currentCodespace = codespace
    async function fetchSkus() {
      try {
        const response = await verifiedFetch(currentCodespace.paths.changeMachineType, {
          headers: {Accept: 'application/json'},
        })
        if (cancelled) return
        if (!response.ok) throw new Error('Failed to load machine types')
        const data = (await response.json()) as SkuData
        setSkuData(data)
        setSelectedSku(data.currentSku)
      } catch {
        if (!cancelled) setError('Failed to load machine types')
      } finally {
        if (!cancelled) setLoading(false)
      }
    }

    void fetchSkus()
    return () => {
      cancelled = true
    }
  }, [codespace])

  const handleSave = useCallback(async () => {
    if (!codespace || !selectedSku) return
    setSaving(true)
    setError(null)

    try {
      const response = await verifiedFetch(codespace.paths.codespace, {
        method: 'PATCH',
        headers: {
          Accept: 'application/json',
          'Content-Type': 'application/x-www-form-urlencoded',
        },
        body: new URLSearchParams({'codespace[sku_name]': selectedSku}),
      })

      if (!response.ok) throw new Error('Failed to update machine type')

      onUpdated()
      onClose()
    } catch {
      setError('Failed to update machine type. Please try again.')
    } finally {
      setSaving(false)
    }
  }, [codespace, selectedSku, onUpdated, onClose])

  if (!codespace) return null

  const hasChanged = selectedSku !== skuData?.currentSku
  const isSelectedDisabled = skuData?.skus.some(s => s.name === selectedSku && !s.enabled)
  const canSave = !saving && !loading && hasChanged && !isSelectedDisabled && !!selectedSku

  return (
    <Dialog
      title="Change codespace machine type"
      onClose={onClose}
      width="large"
      footerButtons={[
        {content: 'Cancel', onClick: onClose},
        {
          content: saving ? 'Updating…' : 'Update codespace',
          buttonType: 'primary',
          onClick: handleSave,
          disabled: !canSave,
        },
      ]}
    >
      <Dialog.Body>
        {loading && (
          <div className="d-flex flex-justify-center tmp-p-3">
            <Spinner size="medium" />
          </div>
        )}
        {error && <Banner hideTitle title="Error" variant="critical" description={error} className="mb-2" />}
        {skuData && (
          <RadioGroup
            name="sku"
            onChange={(value: string | null) => {
              if (value) setSelectedSku(value)
            }}
          >
            <RadioGroup.Label visuallyHidden>Machine type</RadioGroup.Label>
            <div className="border rounded-2 color-border-muted">
              {skuData.skus.map((sku, index) => (
                <div key={sku.name} className={`tmp-p-3${index > 0 ? ' border-top color-border-muted' : ''}`}>
                  <FormControl disabled={!sku.enabled || saving}>
                    <Radio value={sku.name} checked={selectedSku === sku.name} />
                    <FormControl.Label>
                      {sku.cpus}-core
                      <span className="text-small color-fg-muted d-block">
                        {sku.memoryGb}GB RAM &middot; {sku.storageGb}GB
                      </span>
                    </FormControl.Label>
                    {sku.note && <FormControl.Caption>{sku.note}</FormControl.Caption>}
                  </FormControl>
                </div>
              ))}
            </div>
          </RadioGroup>
        )}
      </Dialog.Body>
    </Dialog>
  )
}
