import {BranchName, RelativeTime, Tooltip, Truncate} from '@primer/react'
import {
  ClockIcon,
  DotFillIcon,
  GitPullRequestIcon,
  GitMergeIcon,
  GitPullRequestClosedIcon,
} from '@primer/octicons-react'
import type {Codespace} from './codespaces-types'
import {CodespaceActionMenu} from './CodespaceActionMenu'
import {useAnalytics} from '@github-ui/use-analytics'

interface CodespaceItemProps {
  codespace: Codespace
  showActions: boolean
  onDeleteClick: (codespace: Codespace) => void
  onChangeMachineType: (codespace: Codespace) => void
  onRenameClick: (codespace: Codespace) => void
  onExportClick: (codespace: Codespace) => void
  onActionComplete?: () => void
}

function StatusIndicator({codespace}: {codespace: Codespace}) {
  if (codespace.needsMachineTypeChange) {
    return <span className="text-small color-fg-muted">Machine type disallowed</span>
  }

  if (codespace.needsBaseImageChange) {
    return <span className="text-small color-fg-muted">Image disallowed</span>
  }

  if (codespace.isFailed) {
    return (
      <span className="d-flex flex-items-center text-small color-fg-muted">
        <DotFillIcon className="color-fg-danger" aria-hidden="true" />
        <span>Failed</span>
      </span>
    )
  }

  if (codespace.isBlocking && codespace.blockingOperationText) {
    return <span className="text-small color-fg-muted">{codespace.blockingOperationText}</span>
  }

  if (codespace.isActive) {
    return (
      <span className="d-flex flex-items-center text-small color-fg-muted">
        <DotFillIcon className="color-fg-success" aria-hidden="true" />
        <span>Active</span>
      </span>
    )
  }

  if (codespace.autoDeleteSoon && codespace.retentionExpiresAt) {
    return (
      <span className="d-flex flex-items-center text-small color-fg-muted">
        <ClockIcon className="color-fg-attention mr-1" aria-hidden="true" />
        <span>
          Auto-deletes <RelativeTime datetime={codespace.retentionExpiresAt} />
        </span>
      </span>
    )
  }

  if (codespace.lastUsedAt) {
    return (
      <span className="text-small color-fg-muted">
        <RelativeTime datetime={codespace.lastUsedAt} tense="past" format="micro" />
      </span>
    )
  }

  return null
}

function PullRequestInfo({codespace}: {codespace: Codespace}) {
  if (!codespace.pullRequest) return null

  const PrIcon =
    codespace.pullRequest.state === 'merged'
      ? GitMergeIcon
      : codespace.pullRequest.state === 'closed'
        ? GitPullRequestClosedIcon
        : GitPullRequestIcon

  return (
    <span className="text-small color-fg-muted">
      <PrIcon size={14} className="mr-1 v-align-text-top" />#{codespace.pullRequest.number}
    </span>
  )
}

function GitStatusText({codespace}: {codespace: Codespace}) {
  const commitsText =
    codespace.commitsAhead > 0
      ? `${codespace.commitsAhead} commit${codespace.commitsAhead !== 1 ? 's' : ''} ahead`
      : null

  if (commitsText && codespace.hasUncommittedChanges) {
    return <span>{`${commitsText}, uncommitted changes`}</span>
  }
  if (commitsText) {
    return <span>{commitsText}</span>
  }
  if (codespace.hasUncommittedChanges) {
    return <span>Uncommitted changes</span>
  }
  if (codespace.hasUnpushedChanges) {
    return <span>Unpushed changes</span>
  }
  return null
}

export function CodespaceItem({
  codespace,
  showActions,
  onDeleteClick,
  onChangeMachineType,
  onRenameClick,
  onExportClick,
  onActionComplete,
}: CodespaceItemProps) {
  const nameId = `codespace-name-${codespace.id}`
  const linkDisabled = codespace.linkDisabled
  const displayNameMuted = codespace.isBlocking || codespace.needsMachineTypeChange
  const {sendAnalyticsEvent} = useAnalytics()

  return (
    <li className="d-flex flex-column">
      <div className="flex-1 lh-condensed pt-2 pb-2" style={{minWidth: 0}}>
        <div className="d-flex flex-wrap flex-items-center">
          <div className="d-flex mr-2 flex-1">
            {linkDisabled ? (
              <span className="d-block" id={nameId}>
                <Truncate
                  title={codespace.displayName}
                  maxWidth={250}
                  className={`text-bold ${displayNameMuted ? 'color-fg-muted' : 'color-fg-default'} pb-1`}
                >
                  {codespace.displayName}
                </Truncate>
              </span>
            ) : (
              <Tooltip text={`Open ${codespace.displayName} in editor`} direction="n" type="description">
                <a
                  className="d-block p-0 mt-0 color-fg-muted Link--muted no-underline"
                  href={codespace.openUrl}
                  data-turbo="false"
                  id={nameId}
                  onClick={() => sendAnalyticsEvent('codespace_open.click', 'REPO_PAGE_DROPDOWN')}
                >
                  <Truncate
                    title={codespace.displayName}
                    maxWidth={250}
                    className={`text-bold ${displayNameMuted ? 'color-fg-muted' : 'color-fg-default'} pb-1`}
                  >
                    {codespace.displayName}
                  </Truncate>
                </a>
              </Tooltip>
            )}
          </div>

          <div className="text-small color-fg-muted">
            <StatusIndicator codespace={codespace} />
          </div>

          <div className="ml-1">
            <CodespaceActionMenu
              codespace={codespace}
              showActions={showActions}
              onDeleteClick={onDeleteClick}
              onChangeMachineType={onChangeMachineType}
              onRenameClick={onRenameClick}
              onExportClick={onExportClick}
              onActionComplete={onActionComplete}
            />
          </div>
        </div>

        <div
          className="d-flex flex-row flex-wrap flex-items-baseline text-small color-fg-muted"
          style={{gap: 'var(--base-size-4) var(--base-size-8)'}}
        >
          {!codespace.isUnpublished && (
            <>
              <BranchName className="mr-1">
                <Truncate title={codespace.branch} maxWidth={200}>
                  {codespace.branch}
                </Truncate>
              </BranchName>
              <GitStatusText codespace={codespace} />
            </>
          )}

          {codespace.pullRequest && (
            <>
              <span className="text-small color-fg-muted">&bull;</span>
              <PullRequestInfo codespace={codespace} />
            </>
          )}

          {!codespace.pullRequest && codespace.isReadOnly && (
            <>
              <span className="text-small color-fg-muted">&bull;</span>
              <span>You don&apos;t have push permissions</span>
            </>
          )}

          {!codespace.pullRequest && !codespace.isReadOnly && codespace.isForFork && (
            <>
              <span className="text-small color-fg-muted">&bull;</span>
              <span>
                <span>{codespace.isOwnersFork ? 'From your fork' : 'From fork'}</span>{' '}
                {codespace.forkNwo && <span className="text-bold">{codespace.forkNwo}</span>}
              </span>
            </>
          )}
        </div>
      </div>
    </li>
  )
}
