import {Blankslate} from '@primer/react/experimental'
import type {Codespace, CodespacesData} from './codespaces-types'
import {CodespaceItem} from './CodespaceItem'
import {CodespacesEmptyState} from './CodespacesEmptyState'
import type {CodespacesCreateAction} from './use-codespaces-create-action'
import styles from './CodespacesTabReact.module.css'

interface CodespacesListProps {
  data: CodespacesData
  currentBranchName?: string
  createAction: CodespacesCreateAction
  onDeleteClick: (codespace: Codespace) => void
  onChangeMachineType: (codespace: Codespace) => void
  onRenameClick: (codespace: Codespace) => void
  onExportClick: (codespace: Codespace) => void
  onActionComplete?: () => void
}

function CodespacesSection({
  title,
  codespaces,
  showActions,
  onDeleteClick,
  onChangeMachineType,
  onRenameClick,
  onExportClick,
  onActionComplete,
}: {
  title: string
  codespaces: Codespace[]
  showActions: boolean
  onDeleteClick: (codespace: Codespace) => void
  onChangeMachineType: (codespace: Codespace) => void
  onRenameClick: (codespace: Codespace) => void
  onExportClick: (codespace: Codespace) => void
  onActionComplete?: () => void
}) {
  return (
    <section>
      <h4 className="text-small color-fg-muted pb-1 mb-0">{title}</h4>
      <ul className="list-style-none m-0 p-0">
        {codespaces.map(codespace => (
          <CodespaceItem
            key={codespace.id}
            codespace={codespace}
            showActions={showActions}
            onDeleteClick={onDeleteClick}
            onChangeMachineType={onChangeMachineType}
            onRenameClick={onRenameClick}
            onExportClick={onExportClick}
            onActionComplete={onActionComplete}
          />
        ))}
      </ul>
    </section>
  )
}

export function CodespacesList({
  data,
  currentBranchName,
  createAction,
  onDeleteClick,
  onChangeMachineType,
  onRenameClick,
  onExportClick,
  onActionComplete,
}: CodespacesListProps) {
  const currentBranch = currentBranchName
    ? data.codespaces.filter(codespace => codespace.isForCurrentRepository && codespace.branch === currentBranchName)
    : data.codespaces
  const otherBranches = currentBranchName
    ? data.codespaces
        .filter(codespace => !codespace.isForCurrentRepository || codespace.branch !== currentBranchName)
        .sort((a, b) => {
          if (a.isForCurrentRepository !== b.isForCurrentRepository) {
            return a.isForCurrentRepository ? -1 : 1
          }
          return 0
        })
    : []

  if (data.codespaces.length === 0) {
    return <CodespacesEmptyState header={data.header} createAction={createAction} />
  }

  return (
    <div className={`${styles.CodespaceList} overflow-x-auto tmp-p-3`}>
      {(currentBranch.length > 0 || otherBranches.length > 0) && (
        <CodespacesSection
          title="On current branch"
          codespaces={currentBranch}
          showActions={data.showActions}
          onDeleteClick={onDeleteClick}
          onChangeMachineType={onChangeMachineType}
          onRenameClick={onRenameClick}
          onExportClick={onExportClick}
          onActionComplete={onActionComplete}
        />
      )}

      {currentBranch.length === 0 && otherBranches.length > 0 && (
        <Blankslate narrow>
          <Blankslate.Description>No codespaces on current branch</Blankslate.Description>
        </Blankslate>
      )}

      {otherBranches.length > 0 && (
        <div className="border-top color-border-muted tmp-mt-3 tmp-pt-3">
          <CodespacesSection
            title="On other branches"
            codespaces={otherBranches}
            showActions={data.showActions}
            onDeleteClick={onDeleteClick}
            onChangeMachineType={onChangeMachineType}
            onRenameClick={onRenameClick}
            onExportClick={onExportClick}
            onActionComplete={onActionComplete}
          />
        </div>
      )}
    </div>
  )
}
