import {IconButton, Spinner} from '@primer/react'
import {PlusIcon} from '@primer/octicons-react'
import type {CodespacesHeader} from './codespaces-types'
import type {CodespacesCreateAction} from './use-codespaces-create-action'
import {ConcurrencyLimitDialog} from './ConcurrencyLimitDialog'

export function CodespacesCreateButton({
  header,
  createAction,
}: {
  header: CodespacesHeader
  createAction: CodespacesCreateAction
}) {
  if (!header.canCreate) return null

  if (header.disableOneClickCreation) {
    return (
      <IconButton
        as="a"
        href={createAction.newWithOptionsUrl}
        target="_blank"
        rel="noopener noreferrer"
        icon={PlusIcon}
        aria-label="Configure and create a codespace"
        variant="invisible"
      />
    )
  }

  return (
    <>
      {createAction.isCreating ? (
        <span
          className="d-flex flex-items-center flex-justify-center"
          style={{width: 32, height: 32}}
          role="status"
          aria-label="Creating codespace"
        >
          <Spinner size="small" />
        </span>
      ) : (
        <IconButton
          onClick={createAction.handleCreate}
          icon={PlusIcon}
          aria-label={`Create a codespace on ${createAction.displayCreateRef ?? 'default branch'}`}
          variant="invisible"
        />
      )}
      <ConcurrencyLimitDialog
        isOpen={createAction.showConcurrencyDialog}
        onClose={createAction.closeConcurrencyDialog}
        manageUrl={header.manageUrl}
      />
    </>
  )
}
