import {Checkbox, FormControl, Link, TextInput} from '@primer/react'
import {Dialog} from '@primer/react/experimental'
import {CopyToClipboardButton} from '@github-ui/copy-to-clipboard/Button'
import {useState, useMemo} from 'react'
import {useAnalytics} from '@github-ui/use-analytics'

interface ShareDeepLinkDialogProps {
  isOpen: boolean
  onClose: () => void
  shareUrl: string
}

type SnippetTab = 'url' | 'html' | 'markdown'

function buildBadgeUrl() {
  return new URL('/codespaces/badge.svg', globalThis.location?.origin ?? 'https://github.com').toString()
}

function buildSnippets(url: string, badgeUrl: string) {
  const badgeAlt = 'Open in GitHub Codespaces'
  // eslint-disable-next-line github/unescaped-html-literal
  const html = `<a href="${url}"><img src="${badgeUrl}" alt="${badgeAlt}" /></a>`
  const markdown = `[![${badgeAlt}](${badgeUrl})](${url})`
  return {url, html, markdown}
}

export function ShareDeepLinkDialog({isOpen, onClose, shareUrl}: ShareDeepLinkDialogProps) {
  const [quickStart, setQuickStart] = useState(false)
  const [activeTab, setActiveTab] = useState<SnippetTab>('url')
  const {sendAnalyticsEvent} = useAnalytics()

  const badgeUrl = useMemo(() => buildBadgeUrl(), [])
  const effectiveUrl = useMemo(() => (quickStart ? `${shareUrl}?quickstart=1` : shareUrl), [shareUrl, quickStart])
  const snippets = useMemo(() => buildSnippets(effectiveUrl, badgeUrl), [badgeUrl, effectiveUrl])

  if (!isOpen) return null

  const tabItems: Array<{id: SnippetTab; label: string}> = [
    {id: 'url', label: 'URL'},
    {id: 'html', label: 'HTML'},
    {id: 'markdown', label: 'Markdown'},
  ]

  return (
    <Dialog
      title="Share codespace configuration"
      subtitle="Choose which settings from this configuration to include when sharing"
      onClose={onClose}
      width="xlarge"
    >
      <Dialog.Body>
        <div className="border-bottom color-border-muted tmp-pb-3 tmp-mb-3">
          <FormControl>
            <Checkbox checked={quickStart} onChange={e => setQuickStart(e.target.checked)} />
            <FormControl.Label>Quick start</FormControl.Label>
            <FormControl.Caption>
              Automatically create or reuse the most recent matching codespace.{' '}
              <Link
                inline
                href="https://docs.github.com/codespaces/setting-up-your-project-for-codespaces/setting-up-your-repository/facilitating-quick-creation-and-resumption-of-codespaces#creating-a-link-to-resume-a-codespace"
                target="_blank"
              >
                Read more about creating a link.
              </Link>
            </FormControl.Caption>
          </FormControl>
        </div>

        <div className="text-bold mb-1">Snippets</div>
        <div className="text-small color-fg-muted mb-2">
          Use the following snippets to embed an &ldquo;Open in Codespaces&rdquo; button for this configuration in your
          own page or README.
        </div>

        <div
          className="UnderlineNav mb-2"
          role="tablist"
          aria-label="Snippet format"
          style={{justifyContent: 'flex-start'}}
        >
          {tabItems.map(tab => (
            <button
              key={tab.id}
              type="button"
              role="tab"
              aria-selected={activeTab === tab.id}
              aria-controls="snippet-tabpanel"
              className={`UnderlineNav-item ${activeTab === tab.id ? 'selected' : ''}`}
              onClick={() => setActiveTab(tab.id)}
            >
              {tab.label}
            </button>
          ))}
        </div>

        <div id="snippet-tabpanel" role="tabpanel">
          {(activeTab === 'html' || activeTab === 'markdown') && (
            <div className="border color-border-muted rounded-2 tmp-p-3 mb-2 d-flex flex-justify-center">
              <img src={badgeUrl} alt="Open in GitHub Codespaces" />
            </div>
          )}
          <TextInput
            readOnly
            value={snippets[activeTab]}
            aria-label={`${activeTab.toUpperCase()} snippet`}
            block
            trailingAction={
              <CopyToClipboardButton
                textToCopy={snippets[activeTab]}
                ariaLabel="Copy to clipboard"
                onCopy={() => sendAnalyticsEvent('codespace_share.click', activeTab.toUpperCase())}
              />
            }
          />
        </div>
      </Dialog.Body>
    </Dialog>
  )
}
